package com.termux.app.workspace;

import android.app.*;
import android.widget.*;
import org.json.*;
import java.util.*;
import java.util.concurrent.*;

/** On-demand OpenCode settings; no polling, terminal injection or process replacement. */
final class OpenCodeStatusUi {
    interface Rpc {JSONObject call(JSONObject request)throws Exception;}
    private final Activity activity;private final WorkspaceStore.Session profile,source;private final Runnable changed;private final Rpc rpc;
    private final ExecutorService worker=Executors.newSingleThreadExecutor();private final String thread,connection,handle;
    private AlertDialog dialog;private TextView model,reasoning,mode,rights,info;private JSONArray variants=new JSONArray();private JSONObject state,settings;private boolean closed,busy;
    private Runnable chatPreview=()->{},chatSave=()->{};
    void chatPresentation(Runnable preview,Runnable save){chatPreview=preview;chatSave=save;}
    OpenCodeStatusUi(Activity a,WorkspaceStore.Session p,Runnable changed,Rpc rpc){activity=a;profile=p;this.changed=changed;source=AiAgents.snapshot(p);thread=p.aiThread;connection=p.aiConnection;handle=p.handle;this.rpc=rpc==null?q->AiAgents.call(a,connection,source,q):rpc;}
    private String tr(String ru,String en){return AgentStatusUi.tr(activity,ru,en);}
    private boolean owns(){return !closed&&!activity.isFinishing()&&!activity.isDestroyed()&&thread.equals(profile.aiThread)&&connection.equals(profile.aiConnection)&&handle.equals(profile.handle)&&source.aiSocketId.equals(profile.aiSocketId);}
    private boolean canChange(){return !busy&&settings!=null&&settings.optBoolean("canChange");}
    private Runnable launchPermissions;
    private int section;
    OpenCodeStatusUi launchPermissions(Runnable action){launchPermissions=action;return this;}
    void showModels(){show(1);}
    void showLimits(){show(2);}
    void showPermissions(){show(3);}
    void show(){show(0);}
    private void show(int section){this.section=section;LinearLayout body=AgentStatusUi.body(activity);model=AgentStatusUi.row(body,"","model",this::chooseModel);reasoning=AgentStatusUi.row(body,"","reasoning",this::chooseReasoning);rights=AgentStatusUi.row(body,"","permissions",()->choose(true));mode=AgentStatusUi.row(body,"","mode",()->choose(false));info=AgentStatusUi.info(body,"");info.setId(android.R.id.message);if(section==3){body.removeView(model);body.removeView(reasoning);if(launchPermissions!=null)AgentStatusUi.row(body,tr("Ограничение внешних путей · после перезапуска","External-path restriction · after restart"),"launch-scope",launchPermissions);}else if(section==1){body.removeAllViews();body.addView(model);body.addView(reasoning);}else if(section==2){body.removeView(model);body.removeView(reasoning);body.removeView(rights);body.removeView(mode);}
        dialog=WorkspaceDialogs.builder(activity).setTitle(section==3?tr("Права и подтверждения · OpenCode","Permissions and approvals · OpenCode"):section==1?tr("Модель OpenCode","OpenCode model"):tr("Лимиты и контекст · OpenCode","Limits and context · OpenCode")).setView(AgentStatusUi.scroll(body)).setPositiveButton(tr("Обновить","Refresh"),null).setNegativeButton(tr("Закрыть","Close"),null).create();dialog.setOnDismissListener(d->{closed=true;worker.shutdown();});dialog.setOnShowListener(d->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->refresh()));dialog.show();if(section==1)dialog.getButton(AlertDialog.BUTTON_POSITIVE).setVisibility(android.view.View.GONE);render("");refresh();}
    private void render(String notice){if(!owns())return;model.setText(tr("Модель: ","Model: ")+modelValue()+" ›");AgentStatusUi.available(model,!busy&&state!=null);reasoning.setText(tr("Рассуждение: ","Reasoning: ")+reasoningValue());reasoning.setVisibility(variants.length()>0?android.view.View.VISIBLE:android.view.View.GONE);AgentStatusUi.available(reasoning,!busy&&state!=null&&variants.length()>0);
        String access=settings==null?"":settings.optString("access"),agent=settings==null?"":settings.optString("mode");rights.setText(tr("Действующие права: ","Active permissions: ")+(access.isEmpty()?tr("Нет данных","No data"):access.equals("custom")?tr("Свои правила","Custom rules"):AiAgentsUi.accessLabel(access))+" ›");mode.setText(tr("Действующий режим: ","Active mode: ")+(agent.isEmpty()?tr("Нет данных","No data"):agent)+" ›");AgentStatusUi.available(rights,canChange());AgentStatusUi.available(mode,canChange());
        String status=busy?tr("Получение подтверждения…","Waiting for confirmation…"):state==null?tr("Нет подключения к локальному серверу.","No local server connection."):tr("Подключено к локальному серверу. Доступ к провайдеру проверяется при запросе.","Connected to the local server. Provider access is checked when sending a request.");
        String scope=settings==null?"":settings.optString("scope");String scopeText=scope.isEmpty()?tr("Действующее ограничение внешних путей: Нет данных","Active external-path restriction: No data"):scope.equals("project")?tr("Работа в пределах проекта: внешние каталоги, shell и внешние инструменты запрещены правилами запуска.","Project scope: launch rules deny external directories, shell and external tools."):tr("Внешние каталоги регулируются выбранными правами OpenCode.","Selected OpenCode permissions govern external directories.");
        String permissionInfo=scopeText+"\n\n"+(settings==null?tr("Действующие права не подтверждены. Обновите данные; если маршрут не поддерживает переключение, сохраните настройки для следующего запуска.","Active permissions are not confirmed. Refresh; if this route does not support switching, save settings for the next launch."):canChange()?"":tr("Переключение доступно, когда чат свободен, нет вопросов/подтверждений и терминальное окно закрыто.","Switching is available when chat is idle, no questions/approvals are pending and the native terminal is closed."));
        String limitInfo=tr("Остаток лимитов аккаунта и текущий контекст этим каналом не предоставляются.","Remaining account limits and current context are not supplied by this channel.");
        info.setText(status+"\n\n"+(section==3?permissionInfo:section==2?limitInfo:permissionInfo+"\n\n"+limitInfo)+(notice.isEmpty()?"":"\n\n"+notice));
        dialog.getButton(AlertDialog.BUTTON_POSITIVE).setEnabled(!busy);dialog.getButton(AlertDialog.BUTTON_NEGATIVE).setEnabled(!busy);dialog.setCancelable(!busy);dialog.setCanceledOnTouchOutside(!busy);
    }
    static boolean validSettings(JSONObject value,String session){return value!=null&&session.equals(value.optString("session"))&&value.optString("revision").matches("[0-9a-f]{64}")&&Arrays.asList("project","unrestricted").contains(value.optString("scope"))&&Arrays.asList("full","ask","read","custom").contains(value.optString("access"))&&Arrays.asList("build","plan","custom").contains(value.optString("mode"));}
    private void refresh(){if(!owns()||busy)return;busy=true;render("");worker.execute(()->{JSONObject next=null,config=null;JSONArray options=new JSONArray();try{next=rpc.call(AiAgentsUi.op("status"));if(section==1){JSONObject catalog=rpc.call(AiAgentsUi.op("models"));JSONArray models=catalog.optJSONArray("models");JSONObject actual=next.optJSONObject("model");if(models!=null&&actual!=null)for(int i=0;i<models.length();i++){JSONObject item=models.optJSONObject(i);if(item!=null&&item.optString("provider").equals(actual.optString("providerID"))&&item.optString("id").equals(actual.optString("id"))&&item.optJSONArray("variants")!=null){options=item.optJSONArray("variants");break;}}}if(next.optBoolean("nativeChat"))try{JSONObject read=rpc.call(AiAgentsUi.op("settings-read"));if(validSettings(read,next.optString("id")))config=read;}catch(Exception ignored){}}catch(Exception ignored){}JSONObject value=next,settingsValue=config;JSONArray variantOptions=options;activity.runOnUiThread(()->{if(!owns())return;busy=false;state=value;settings=settingsValue;variants=variantOptions;render("");});});}
    private void choose(boolean permissions){if(!owns()||!canChange())return;JSONObject captured=settings;String[] codes=permissions?new String[]{"full","ask","read"}:new String[]{"build","plan"};String[] labels=new String[codes.length];for(int i=0;i<codes.length;i++)labels[i]=permissions?AiAgentsUi.accessLabel(codes[i])+"\n"+AiAgentsUi.accessDescription(codes[i]):codes[i]+"\n"+AiAgentsUi.modeDescription(codes[i]);int checked=Arrays.asList(codes).indexOf(captured.optString(permissions?"access":"mode"));
        WorkspaceDialogs.builder(activity).setTitle(permissions?tr("Права OpenCode","OpenCode permissions"):tr("Режим OpenCode","OpenCode work mode")).setSingleChoiceItems(labels,checked,(d,w)->{d.dismiss();WorkspaceDialogs.builder(activity).setTitle(tr("Подтвердить выбор","Confirm selection")).setMessage(labels[w]+"\n\n"+tr("Применяется к текущему чату и сохраняется в его настройках после подтверждения сервера. Текущие правила этого чата будут заменены; ограничение проекта остаётся прежним.","Applies to this chat and is saved after server confirmation. This chat's current rules will be replaced; its project scope stays unchanged.")).setPositiveButton(tr("Применить","Apply"),(confirm,index)->apply(captured,permissions,codes[w])).setNegativeButton(tr("Назад","Back"),null).show();}).setNegativeButton(tr("Назад","Back"),null).show();
    }
    private void apply(JSONObject captured,boolean permissions,String value){if(!owns()||busy)return;String before=permissions?profile.aiAccess:profile.aiMode;JSONObject request=AiAgentsUi.op(permissions?"settings-permissions":"settings-mode");try{request.put("id","cfg_"+UUID.randomUUID()).put("session",captured.getString("session")).put("revision",captured.getString("revision")).put(permissions?"access":"mode",value);}catch(JSONException invalid){return;}busy=true;render("");worker.execute(()->{JSONObject result=null;try{result=rpc.call(request);}catch(Exception ignored){}JSONObject response=result;activity.runOnUiThread(()->{if(!owns())return;busy=false;JSONObject actual=response==null?null:response.optJSONObject("settings");if(!validSettings(actual,captured.optString("session"))){settings=null;render(tr("Изменение не подтверждено. Права могли измениться; обновите данные перед повтором. Настройки запуска не сохранены.","Change not confirmed. Permissions may have changed; refresh before retrying. Launch settings were not saved."));return;}settings=actual;
            if(response.optBoolean("applied")&&value.equals(actual.optString(permissions?"access":"mode"))){if(before.equals(permissions?profile.aiAccess:profile.aiMode)){if(permissions)profile.aiAccess=value;else profile.aiMode=value;changed.run();render(tr("Выбор подтверждён сервером. Настройки сессии обновлены.","Selection confirmed by server. Session settings updated."));}else render(tr("Сервер применил выбор, но настройки были изменены отдельно. Проверьте пресет.","Server applied the selection, but settings changed separately. Check the preset."));}
            else render(tr("Выбор не применён: чат занят или настройки изменились. Обновите данные и повторите выбор.","Selection not applied: chat is busy or settings changed. Refresh and choose again."));
        });});}
    private String modelValue(){JSONObject actual=state==null?null:state.optJSONObject("model");String value=actual==null?"":actual.optString("id");if(value.isEmpty()&&!profile.aiModel.isEmpty()){int slash=profile.aiModel.indexOf('/');value=slash<0?profile.aiModel:profile.aiModel.substring(slash+1);}return value.isEmpty()?tr("По умолчанию","Default"):value;}
    private String reasoningValue(){JSONObject actual=state==null?null:state.optJSONObject("model");String value=actual==null?profile.aiVariant:actual.optString("variant");return value.isEmpty()?tr("По умолчанию","Default"):value;}
    private void chooseReasoning(){if(!owns()||busy||state==null||variants.length()==0)return;JSONObject actual=state.optJSONObject("model");if(actual==null)return;List<String> values=new ArrayList<>(),names=new ArrayList<>();values.add("");names.add(tr("По умолчанию","Default"));for(int i=0;i<variants.length();i++){JSONObject item=variants.optJSONObject(i);if(item!=null&&!item.optString("id").isEmpty()){values.add(item.optString("id"));names.add(item.optString("id"));}}
        WorkspaceDialogs.builder(activity).setTitle(tr("Рассуждение","Reasoning")).setSingleChoiceItems(names.toArray(new String[0]),values.indexOf(actual.optString("variant")),(d,w)->{d.dismiss();confirmModel(actual.optString("providerID"),actual.optString("id"),values.get(w));}).setNegativeButton(tr("Отмена","Cancel"),null).show();}
    private void chooseModel(){if(!owns()||busy||state==null)return;AiAgentsUi.chooseModel(activity,connection,source,this::confirmModel);}
    private void confirmModel(String provider,String id,String variant){if(!owns())return;WorkspaceDialogs.builder(activity).setTitle(tr("Сменить модель?","Change model?")).setMessage(provider+" / "+id+(variant.isEmpty()?"":" · "+variant)+"\n\n"+tr("История чата сохраняется. Дождитесь завершения ответа.","Chat history is preserved. Wait for the current response to finish.")).setPositiveButton(tr("Применить","Apply"),(d,w)->{if(!owns()||busy)return;JSONObject q=AiAgentsUi.op("model");try{q.put("provider",provider).put("model",id).put("variant",variant).put("reopen",true);}catch(JSONException ignored){return;}busy=true;render("");worker.execute(()->{JSONObject result=null;try{result=rpc.call(q);}catch(Exception ignored){}JSONObject r=result;activity.runOnUiThread(()->{if(!owns())return;busy=false;if(r!=null&&r.optBoolean("applied")&&r.optBoolean("reopened")&&r.optJSONObject("model")!=null){if(AiAgentsUi.showConfirmedModel(profile,r.optJSONObject("model"),model,changed)){try{state.put("model",r.optJSONObject("model"));}catch(JSONException impossible){throw new IllegalStateException(impossible);}refresh();}else render(tr("Некорректный ответ о модели. Обновите данные.","Invalid model response. Refresh the data."));}else render(tr("Смена модели не подтверждена. Обновите данные перед повтором.","Model change not confirmed. Refresh before retrying."));});});}).setNegativeButton(tr("Назад","Back"),null).show();}
}
